function [audit,status]=run_q9_dom_cohort(phase_key,subject_numbers)
% Q9 DOM cohort: DivisionOfMesoappendixHILE + DivisionOfMesoappendixHIHE
% minus the explicit ExperimentalBaseline boxcar. Subject001 is pilot-only.
if nargin<1||isempty(phase_key),phase_key="dom";end; if nargin<2,subject_numbers=2:30;end; phase_key=lower(string(phase_key));assert(any(phase_key==["dom","aoe"]));assert(~ismember(1,subject_numbers));
repo=fileparts(fileparts(fileparts(fileparts(mfilename('fullpath')))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');
root=fullfile(repo,'results',char("q9_high_intrinsic_vs_experimentalbaseline_"+phase_key),'cohort_specification');if ~isfolder(root),mkdir(root);end
ef=fullfile(glm,'amended_snirf','event_tables_full_annotations','event_table_all_subjects_full_annotations.csv');E=readtable(ef,'TextType','string');E.subject_id=string(compose('%03d',double(E.subject_id)));E.condition=string(E.condition);
addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));
if phase_key=="dom", target_labels=["DivisionOfMesoappendixHILE","DivisionOfMesoappendixHIHE"]; phase_tag="dom"; else, target_labels=["ApplicationOfEndoloopsHILE","ApplicationOfEndoloopsHIHE"]; phase_tag="aoe"; end
audit=table();for i=1:30
 sid=string(compose('%03d',i));sub=E(E.subject_id==sid,:);infile=fullfile(fl,'nirs_spm_inputs',char("subject"+sid),char("subject"+sid+"_nirs_data.mat"));nb=sum(sub.condition=="ExperimentalBaseline");nl=sum(sub.condition==target_labels(1));nh=sum(sub.condition==target_labels(2));ok=nb==1&&nl>=1&&nh>=1&&isfile(infile);reason="included";if ~ok,rs=strings(0,1);if nb~=1,rs(end+1)="ExperimentalBaseline count is not 1";end;if nl<1,rs(end+1)=phase_tag+" HILE missing";end;if nh<1,rs(end+1)=phase_tag+" HIHE missing";end;if ~isfile(infile),rs(end+1)="continuous input missing";end;reason=strjoin(rs,'; ');end;audit=[audit;table(sid,i,nb,nl,nh,isfile(infile),ok,string(infile),reason,'VariableNames',{'subject_id','subject_num','experimentalbaseline_n','phase_hile_n','phase_hihe_n','input_exists','included','nirs_data_file','exclusion_reason'})]; %#ok<AGROW>
end
writetable(audit,fullfile(root,char("q9_"+phase_key+"_event_availability_audit_n30.csv")));assert(sum(audit.included)==29);
status=table();target_name=char("HILoad_"+phase_key+"_HRF");
for i=subject_numbers
 sid=string(compose('%03d',i));ar=audit(audit.subject_id==sid,:);if ~ar.included,status=[status;table(sid,"excluded",ar.exclusion_reason,'VariableNames',{'subject_id','status','detail'})];continue;end
 sr=fullfile(root,char("subject"+sid));if ~isfolder(sr),mkdir(sr);end
 try
  infile=char(ar.nirs_data_file);D=load(infile,'nirs_data');ns=size(D.nirs_data.oxyData,1);fs=double(D.nirs_data.fs);scan=(0:ns-1)'/fs;sub=E(E.subject_id==sid,:);base=sortrows(sub(sub.condition=="ExperimentalBaseline",:),'onset_sec');tar=sortrows(sub(ismember(sub.condition,target_labels),:),'onset_sec');box=scan>=double(base.onset_sec)&scan<double(base.onset_sec+base.duration_sec);assert(any(box)&&any(~box));
  sel=[base;tar];sel.role=[repmat("ExperimentalBaseline_boxcar",height(base),1);repmat("HILoad_phase_HRF",height(tar),1)];sel.selection_policy=["single ExperimentalBaseline event";repmat("all HILE/HIHE events merged for "+phase_tag,height(tar),1)];sel.input_file=repmat(string(infile),height(sel),1);writetable(sel,fullfile(sr,char(sid+"_q9_"+phase_key+"_selected_events.csv")));writetable(table(repmat(sid,ns,1),(1:ns)',scan,double(box),'VariableNames',{'subject_id','scan_index','scan_time_sec','ExperimentalBaseline_boxcar'}),fullfile(sr,char(sid+"_q9_"+phase_key+"_baseline_boxcar_audit.csv")));
  names={target_name};onsets={double(tar.onset_sec(:)')};durations={double(tar.duration_sec(:)')};save(fullfile(sr,char(sid+"_q9_"+phase_key+"_merged_task_definition.mat")),'names','onsets','durations','target_labels');qa=table();hbs=["HbO","HbR"];
  for ih=1:2
   hb=hbs(ih);short='hbr';if hb=="HbO",short='hbo';end;hr=fullfile(sr,char(hb));if ~isfolder(hr),mkdir(hr);end;specification_batch(infile,short,'DCT, 128','none',0,char(hr),0,0,1,names,onsets,durations);sf=fullfile(hr,sprintf('SPM_indiv_%s.mat',hb));L=load(sf,'SPM_nirs');S=addbase(L.SPM_nirs,box,target_name);S.nirs.step='specification';S=rebuild(S);SPM_nirs=S;save(sf,'SPM_nirs');[qr,rt,pair]=qa_design(S,sid,hb);qa=[qa;qr]; %#ok<AGROW>;writematrix(full(S.xX.X),fullfile(hr,char(sid+"_"+hb+"_q9_"+phase_key+"_final_design.csv")));writetable(rt,fullfile(hr,char(sid+"_q9_"+phase_key+"_regressor_table.csv")));writetable(pair,fullfile(hr,char(sid+"_q9_"+phase_key+"_pairwise_correlation_vif.csv")));
  end
  A=load(fullfile(sr,'HbO','SPM_indiv_HbO.mat'),'SPM_nirs');B=load(fullfile(sr,'HbR','SPM_indiv_HbR.mat'),'SPM_nirs');hcheck1=isequal(A.SPM_nirs.xX.X(:,1),B.SPM_nirs.xX.X(:,1));hcheck2=isequal(A.SPM_nirs.xX.X(:,3),B.SPM_nirs.xX.X(:,3));hcheck3=max(abs(full(A.SPM_nirs.xX.X(:,2))+full(B.SPM_nirs.xX.X(:,2))));assert(all(qa.qa_pass));assert(hcheck1&&hcheck2&&hcheck3<1e-10);writetable(qa,fullfile(sr,char(sid+"_q9_"+phase_key+"_design_qa.csv")));
  for ih=1:2,hb=hbs(ih);sf=fullfile(sr,char(hb),sprintf('SPM_indiv_%s.mat',hb));nirs_spm_estimation_batch_fixed(sf,infile);L=load(sf,'SPM_nirs');writecontrast(L.SPM_nirs,sid,hb,sr,fl,target_name,phase_key);end
  status=[status;table(sid,"completed","", 'VariableNames',{'subject_id','status','detail'})]; %#ok<AGROW>
 catch ME,disp(getReport(ME,'extended','hyperlinks','off'));status=[status;table(sid,"failed",string(ME.message),'VariableNames',{'subject_id','status','detail'})]; %#ok<AGROW>
 end
 writetable(status,fullfile(root,char("q9_"+phase_key+"_estimation_manifest_progress.csv")));
end
writetable(status,fullfile(root,char("q9_"+phase_key+"_estimation_manifest_remaining_subjects.csv")));assert(~any(status.status=="failed"));
end
function S=addbase(S,box,target)
X=full(S.xX.X);n=string(S.xX.name(:));ti=find(contains(n,target),1);ci=find(contains(lower(n),'constant'),1);S.xX.X=[double(box(:)),X(:,ti),X(:,ci)];S.xX.name={'Sn(1) ExperimentalBaseline_boxcar (unconvolved)',char(n(ti)),'Sn(1) constant'};S.xX.iH=[];S.xX.iC=[1 2];S.xX.iB=3;S.xX.iG=[];S.Sess(1).C.C=double(box(:));S.Sess(1).C.name={'ExperimentalBaseline_boxcar (unconvolved)'};S.Sess(1).col=[1 2];for f={'xKXs','pKX','Bcov'},if isfield(S.xX,f{1}),S.xX=rmfield(S.xX,f{1});end,end
end
function S=rebuild(S),S.xX.xKXs=spm_sp('Set',spm_filter_HPF_LPF_WMDL(S.xX.K,S.xX.X));S.xX.xKXs.X=full(S.xX.xKXs.X);S.xX.pKX=spm_sp('x-',S.xX.xKXs);end
function [q,row,pair]=qa_design(S,sid,hb),X=full(S.xX.X);n=string(S.xX.name(:));b=X(:,1);t=X(:,2);bc=b-mean(b);tc=t-mean(t);r=(bc'*tc)/sqrt((bc'*bc)*(tc'*tc));Z=[ones(size(b)),b];r2=1-sum((t-Z*(Z\t)).^2)/sum((t-mean(t)).^2);v=1/max(1-r2,eps);q=table(sid,hb,size(X,1),size(X,2),rank(X),r,v,rank(X)==3&&abs(r)<.95&&v<=10,'VariableNames',{'subject_id','hemoglobin','n_scans','n_columns','rank','task_baseline_correlation','task_vif','qa_pass'});row=table((1:3)',n,[true;false;false],[false;true;false],[false;false;true],'VariableNames',{'column_index','regressor','is_unconvolved_baseline','is_hrf_convolved_task','is_constant'});pair=table("ExperimentalBaseline_boxcar","HILoad_dom_HRF",r,v,abs(r)<.95&&v<=10,'VariableNames',{'regressor_1','regressor_2','correlation','vif_for_task','qa_pass'});end
function writecontrast(S,sid,hb,sr,fl,target,phase_key),n=string(S.xX.name(:));ib=find(contains(n,'ExperimentalBaseline_boxcar'),1);it=find(contains(n,target),1);c=zeros(3,1);c(ib)=-1;c(it)=1;B=double(S.nirs.beta);rss=double(S.nirs.ResSS);if ~isvector(rss),rss=diag(rss)';end;df=double(S.xX.erdf);be=c'*B;se=sqrt(max((c'*double(S.xX.Bcov)*c).*(rss/df),0));tt=be./se;p=betainc(df./(df+tt.^2),df/2,.5);q=bh(p);sd=char("subject"+sid);M=readtable(fullfile(fl,'nirs_spm_inputs',sd,[sd '_channel_metadata.csv']),'TextType','string');nc=size(B,2);T=table(repmat(sid,nc,1),repmat(hb,nc,1),(1:nc)',string(M.channel_id),string(M.channel_type),string(M.roi),string(M.laterality),be(:),se(:),tt(:),p(:),q(:),repmat(join(string(c'),' '),nc,1),'VariableNames',{'subject_id','hemoglobin','channel_index','channel_id','channel_type','roi','laterality','contrast_beta','contrast_se','contrast_t','contrast_p_two_sided','contrast_q_bh61','contrast_vector'});writetable(T,fullfile(sr,char(sid+"_"+hb+"_q9_high_intrinsic_minus_experimentalbaseline_"+phase_key+"_channel_contrasts.csv")));end
function q=bh(p),q=nan(size(p));v=isfinite(p);pv=p(v);[s,o]=sort(pv(:));m=numel(s);a=min(1,flipud(cummin(flipud(s.*m./(1:m)'))));z=zeros(size(pv));z(o)=a;ii=find(v);q(ii)=z;end
